import { Array, flow } from "effect"

type Order = {
  readonly reference: string
  readonly subtotal: number
  readonly discount: number
  readonly taxRate: number
}

type SettlementLine = {
  readonly reference: string
  readonly amount: number
}

const calculateNet = (order: Order): SettlementLine => ({
  reference: order.reference,
  amount: (order.subtotal - order.discount) * (1 + order.taxRate)
})

const roundAmount = (line: SettlementLine): SettlementLine => ({
  reference: line.reference,
  amount: Math.round(line.amount * 100) / 100
})

export const buildSettlementPreview = (
  orders: ReadonlyArray<Order>,
  currency: string
) => ({
  currency,
  orderCount: orders.length,
  lines: Array.map(orders, flow(calculateNet, roundAmount))
})
